solution.js:
let expenses = [{ id: "exp-1", label: "Train", amount: 1220 }];
let count = 1;
const nextId = () => `exp-${++count}`;

const form = document.querySelector("#expense-form");
const errorEl = document.querySelector("#form-error");
const list = document.querySelector("#expense-list");
const formatMoney = (cents) => `$${(cents / 100).toFixed(2)}`;

function renderExpenses() {
  list.replaceChildren();
  for (const e of expenses) {
    const li = document.createElement("li");
    li.textContent = `${e.label}: ${formatMoney(e.amount)}`;
    list.append(li);
  }
}
renderExpenses();

function validateExpense({ label, amount }) {
  const errors = {};
  if (label.trim() === "") {
    errors.label = "Enter what you spent money on.";
  }
  if (!Number.isFinite(amount) || amount <= 0) {
    errors.amount = "Enter an amount greater than zero.";
  }
  return errors;
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  const data = new FormData(form);
  const values = {
    label: data.get("label").trim(),
    amount: Math.round(Number(data.get("amount")) * 100),
  };

  for (const field of form.querySelectorAll("input")) {
    field.removeAttribute("aria-invalid");
  }

  const errors = validateExpense(values);
  const names = Object.keys(errors);
  if (names.length > 0) {
    errorEl.textContent = Object.values(errors).join(" ");
    const firstBad = form.elements[names[0]];
    firstBad.setAttribute("aria-invalid", "true");
    firstBad.focus();
    return;
  }

  errorEl.textContent = "";
  expenses = [...expenses, { id: nextId(), ...values }];
  renderExpenses();
  form.reset();
  form.elements.label.focus();
});

